  createdAt: string
  updatedAt?: string | null
  authorUserId?: string | null
  authorName?: string | null
  authorEmail?: string | null
  dealId?: string | null
  dealTitle?: string | null
  appearanceIcon?: string | null
  appearanceColor?: string | null
}

export type NotesCreatePayload = {
  entityId: string
  body: string
