  appearanceColor?: string | null
}

export type NotesDataAdapter<C = unknown> = {
  list: (params: { entityId: string | null; dealId: string | null; context?: C }) => Promise<CommentSummary[]>
  listPage?: (params: {
    entityId: string | null
    dealId: string | null
