                    : label('saving', 'Saving…')}
                </>
              ) : editingId ? (
                label('update', 'Update address')
              ) : (
                label('save', 'Save address')
              )}
            </Button>
          </div>
        </div>
      </div>
    ),
    [
      addressTypesAdapter,
      addressTypesContext,
      disableActions,
      draft,
      editingId,
      fieldErrors,
      format,
      formatLoading,
      handleCancel,
      handleSave,
      generalError,
      label,
      labelPrefix,
      saving,
      showCoordinateFields,
      t,
    ]
  )

  return (
    <div className="space-y-4">
      {!hideAddButton && hasAddresses ? (
        <div className="flex justify-end">
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={openCreateForm}
            disabled={addDisabled}
          >
            <Plus className="mr-2 h-4 w-4" />
            {label('add', 'Add address')}
          </Button>
        </div>
      ) : null}
      {hasAddresses ? (
        <div className={gridClassName}>
          {addresses.map((address) => {
            if (isFormOpen && editingId === address.id) {
              return renderFormTile(`form-${address.id}`)
            }
            const isDeleting = deletingId === address.id
            return (
              <div
                key={address.id}
                className="group rounded-lg border border-border/70 bg-card p-4 text-sm transition hover:border-border"
