  'inline-block size-4 rounded-full border border-foreground/10 transition-transform ' +
    'group-enabled/swatch:group-hover/swatch:scale-[0.875]',
  {
    variants: {
      selected: {
        true: 'ring-2 ring-inset ring-background',
        false: '',
