    moduleId: widget.moduleId,
    key: widget.key,
    placement: widget.placement,
  }
}

function hasGrantedWidgetFeatures(
  widget: LoadedWidget,
  grantedFeatures: string[],
  hasBackendChromePayload: boolean,
