    const nextWidget = next[index]
    return (
      nextWidget !== undefined &&
      widget.widgetId === nextWidget.widgetId &&
      widget.moduleId === nextWidget.moduleId &&
      widget.key === nextWidget.key &&
      widget.module === nextWidget.module
