 * }
 *
 * <StatusBadge variant={customerStatusMap[customer.status] ?? 'neutral'} dot>
 *   {t(`customers.status.${customer.status}`)}
 * </StatusBadge>
 */
export type StatusMap<T extends string = string> = Record<T, StatusBadgeVariant>

