    })
    await emitCrudUndoSideEffects({
      dataEngine: getDataEngine(ctx),
      action: 'deleted',
      entity: null,
      identifiers: { id: snapshot.id, tenantId: scope.tenantId, organizationId: scope.organizationId },
      events: agreementCrudEvents,
    })
