export type StorePartitionFilePayload = {
  partitionCode: string
  orgId: string | null | undefined
  tenantId: string | null | undefined
  fileName: string
  buffer: Buffer
}

export type StoredPartitionFile = {
  storagePath: string
  absolutePath: string
  fileName: string
}

/**
 * @deprecated Use `StorageDriverFactory.resolveForPartition()` + `driver.store()` instead.
 */
export async function storePartitionFile(payload: StorePartitionFilePayload): Promise<StoredPartitionFile> {
  const root = resolvePartitionRoot(payload.partitionCode)
  const orgSegment = resolveOrgSegment(payload.orgId ?? null)
  const tenantSegment = resolveTenantSegment(payload.tenantId ?? null)
  const safeName = sanitizeFileName(payload.fileName || 'file')
  const uniqueSuffix = randomUUID().replace(/-/g, '').slice(0, 12)
  const storedName = `${Date.now()}_${uniqueSuffix}_${safeName}`
  const relativePath = path.join(orgSegment, tenantSegment, storedName)
  const absolutePath = path.join(root, relativePath)
  await fs.mkdir(path.dirname(absolutePath), { recursive: true })
  await fs.writeFile(absolutePath, payload.buffer)
  return {
    storagePath: relativePath.replace(/\\/g, '/'),
    absolutePath,
    fileName: storedName,
  }
}

/**
 * @deprecated Use `StorageDriverFactory.resolveForAttachment()` + `driver.read()` / `driver.toLocalPath()` instead.
 */
export function resolveAttachmentAbsolutePath(
  partitionCode: string,
  storagePath: string,
  storageDriver?: string | null
): string {
  if (storageDriver === 'legacyPublic') {
    return resolveContainedPath(process.cwd(), storagePath, resolveLegacyPublicRoot())
  }
  const root = resolvePartitionRoot(partitionCode)
  return resolveContainedPath(root, storagePath)
}

/**
 * @deprecated Use `StorageDriverFactory.resolveForAttachment()` + `driver.delete()` instead.
 */
export async function deletePartitionFile(
  partitionCode: string,
  storagePath: string,
  storageDriver?: string | null
): Promise<void> {
  const absolutePath = resolveAttachmentAbsolutePath(partitionCode, storagePath, storageDriver)
  try {
    await fs.unlink(absolutePath)
  } catch {
    // best-effort removal
  }
}
const MIME_BY_EXTENSION: Record<string, string> = {
  avif: 'image/avif',
  bmp: 'image/bmp',
  csv: 'text/csv',
  gif: 'image/gif',
  jpeg: 'image/jpeg',
  jpg: 'image/jpeg',
  json: 'application/json',
  md: 'text/markdown',
  pdf: 'application/pdf',
  png: 'image/png',
  svg: 'image/svg+xml',
  txt: 'text/plain',
  webp: 'image/webp',
  xhtml: 'application/xhtml+xml',
  xml: 'application/xml',
  zip: 'application/zip',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
}

const ACTIVE_CONTENT_MIME_TYPES = new Set([
  'application/xhtml+xml',
  'application/xml',
  'image/svg+xml',
  'text/html',
  'text/xml',
])

const ACTIVE_CONTENT_EXTENSIONS = new Set(['htm', 'html', 'svg', 'xhtml', 'xml'])

const DANGEROUS_EXECUTABLE_EXTENSIONS = new Set([
  'app',
  'apk',
  'bat',
  'cmd',
  'com',
  'dll',
  'exe',
  'hta',
  'jar',
  'js',
  'jse',
  'lnk',
  'msi',
  'pif',
  'ps1',
  'psm1',
  'reg',
  'scr',
  'sh',
  'vbe',
  'vbs',
  'wsf',
  'wsh',
])

const SAFE_INLINE_MIME_TYPES = new Set([
  'image/avif',
  'image/bmp',
  'image/gif',
  'image/jpeg',
  'image/png',
  'image/webp',
])

export function getAttachmentExtension(fileName: string | null | undefined): string {
  const trimmed = String(fileName ?? '').trim()
  const parts = trimmed.split('.').filter(Boolean)
  if (parts.length < 2) return ''
  return parts[parts.length - 1]!.toLowerCase()
}

export function hasDangerousExecutableExtension(fileName: string | null | undefined): boolean {
  const trimmed = String(fileName ?? '').trim()
  if (!trimmed) return false
  const parts = trimmed.split('.').filter(Boolean)
  if (parts.length < 2) return false
  for (let i = 1; i < parts.length; i += 1) {
    const segment = parts[i]!.toLowerCase().replace(/[^a-z0-9]/g, '')
    if (DANGEROUS_EXECUTABLE_EXTENSIONS.has(segment)) return true
  }
  return false
}

export function sanitizeUploadedFileName(input: string | null | undefined): string {
  const trimmed = String(input ?? '').trim()
  const sanitized = trimmed.replace(/[^a-zA-Z0-9._-]/g, '_')
  const parts = sanitized.split('.').filter(Boolean)
  if (!parts.length) return 'file'
  if (parts.length === 1) return parts[0] || 'file'

  const extension = parts.pop() || ''
  const baseName = parts.join('_').replace(/_+/g, '_').replace(/^_+|_+$/g, '')
  const safeBaseName = baseName || 'file'
  return extension ? `${safeBaseName}.${extension.toLowerCase()}` : safeBaseName
}

function detectMimeTypeFromBuffer(buffer: Buffer): string | null {
  if (buffer.length >= 8) {
    const pngSignature = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]
    if (pngSignature.every((value, index) => buffer[index] === value)) return 'image/png'
  }
  if (buffer.length >= 3 && buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff) {
    return 'image/jpeg'
  }
  if (buffer.length >= 6) {
    const header = buffer.subarray(0, 6).toString('ascii')
    if (header === 'GIF87a' || header === 'GIF89a') return 'image/gif'
  }
  if (buffer.length >= 12) {
    const riff = buffer.subarray(0, 4).toString('ascii')
    const webp = buffer.subarray(8, 12).toString('ascii')
    if (riff === 'RIFF' && webp === 'WEBP') return 'image/webp'
  }
  if (buffer.length >= 4 && buffer.subarray(0, 4).toString('ascii') === '%PDF') {
    return 'application/pdf'
  }
  if (buffer.length >= 4 && buffer[0] === 0x50 && buffer[1] === 0x4b && buffer[2] === 0x03 && buffer[3] === 0x04) {
    return 'application/zip'
  }

  const sniff = buffer.subarray(0, Math.min(buffer.length, 512)).toString('utf8').trimStart().toLowerCase()
  if (sniff.startsWith('<svg') || sniff.startsWith('<?xml') || sniff.startsWith('<!doctype html') || sniff.startsWith('<html')) {
    if (sniff.startsWith('<svg')) return 'image/svg+xml'
    if (sniff.startsWith('<!doctype html') || sniff.startsWith('<html')) return 'text/html'
    return 'application/xml'
  }

  return null
}

export function detectAttachmentMimeType(
  buffer: Buffer,
  fileName: string | null | undefined,
  clientMimeType: string | null | undefined,
): string {
  const detectedFromBuffer = detectMimeTypeFromBuffer(buffer)
  if (detectedFromBuffer) {
    if (
      detectedFromBuffer === 'application/zip' &&
      getAttachmentExtension(fileName) in MIME_BY_EXTENSION
    ) {
      return MIME_BY_EXTENSION[getAttachmentExtension(fileName)] || detectedFromBuffer
    }
    return detectedFromBuffer
  }

  const extension = getAttachmentExtension(fileName)
  if (extension && MIME_BY_EXTENSION[extension]) {
    return MIME_BY_EXTENSION[extension]
  }

  const normalizedClientMimeType = String(clientMimeType ?? '').trim().toLowerCase()
  if (normalizedClientMimeType) return normalizedClientMimeType
  return 'application/octet-stream'
}

export function isActiveContentAttachment(
  buffer: Buffer,
  fileName: string | null | undefined,
  mimeType: string | null | undefined,
): boolean {
  const extension = getAttachmentExtension(fileName)
  if (extension && ACTIVE_CONTENT_EXTENSIONS.has(extension)) return true

  const effectiveMimeType = String(mimeType ?? '').trim().toLowerCase()
  if (effectiveMimeType && ACTIVE_CONTENT_MIME_TYPES.has(effectiveMimeType)) return true

  const sniffedMimeType = detectMimeTypeFromBuffer(buffer)
  return Boolean(sniffedMimeType && ACTIVE_CONTENT_MIME_TYPES.has(sniffedMimeType))
}

export function canRenderInlineAttachment(mimeType: string | null | undefined): boolean {
  return SAFE_INLINE_MIME_TYPES.has(String(mimeType ?? '').trim().toLowerCase())
}

export function buildAttachmentContentDisposition(
  fileName: string | null | undefined,
  dispositionType: 'attachment' | 'inline' = 'attachment',
): string {
  const safeFileName = sanitizeUploadedFileName(fileName)
  return `${dispositionType}; filename="${safeFileName}"; filename*=UTF-8''${encodeURIComponent(safeFileName)}`
}
import fs from 'fs/promises'
import path from 'path'
import { createRequire } from 'module'

const moduleRequire = createRequire(path.join(process.cwd(), 'package.json'))
const pdfJsPackageRoot = path.dirname(moduleRequire.resolve('pdfjs-dist/package.json'))
const cMapUrl = `${path.join(pdfJsPackageRoot, 'cmaps')}${path.sep}`
const standardFontDataUrl = `${path.join(pdfJsPackageRoot, 'standard_fonts')}${path.sep}`

const MIN_RENDER_SCALE = 2
const MAX_RENDER_SCALE = 4
const MAX_RENDER_DIMENSION = 2200
const MAX_RENDER_PIXELS = 8_000_000

type PdfPageProxyLike = {
  cleanup: () => void
  getTextContent: () => Promise<{ items?: Array<{ str?: string }> }>
  getViewport: (args: { scale: number }) => { width: number; height: number }
  render: (args: { canvasContext: unknown; viewport: { width: number; height: number } }) => { promise: Promise<void> }
}

type PdfCanvasFactoryLike = {
  create: (width: number, height: number) => {
    canvas: { toBuffer: (mimeType: string) => Buffer | Uint8Array }
    context: unknown
  }
  destroy: (canvasAndContext: {
    canvas: { toBuffer: (mimeType: string) => Buffer | Uint8Array } | null
    context: unknown
  }) => void
}

type PdfDocumentProxyLike = {
  numPages: number
  canvasFactory: PdfCanvasFactoryLike
  getPage: (pageNumber: number) => Promise<PdfPageProxyLike>
}

export type PdfPageOcrInput = {
  pageNumber: number
  extractedText: string | null
  imageBuffer: Buffer | null
}

export type PdfOcrPreparationResult = {
  pageCount: number
  pages: PdfPageOcrInput[]
}

function normalizePdfText(rawText: string): string | null {
  const normalized = rawText.replace(/\s+/g, ' ').trim()
  return normalized.length > 0 ? normalized : null
}

function extractPdfTextContent(items: Array<{ str?: string }> | undefined): string | null {
  if (!Array.isArray(items) || items.length === 0) return null
  const collected = items
    .map((item) => (typeof item?.str === 'string' ? item.str : ''))
    .filter((value) => value.length > 0)
    .join(' ')
  return normalizePdfText(collected)
}

function resolvePdfRenderScale(page: PdfPageProxyLike): number {
  const baseViewport = page.getViewport({ scale: 1 })
  const baseLargestDimension = Math.max(baseViewport.width, baseViewport.height)
  let scale = Math.min(
    MAX_RENDER_SCALE,
    Math.max(MIN_RENDER_SCALE, MAX_RENDER_DIMENSION / Math.max(baseLargestDimension, 1)),
  )

  let viewport = page.getViewport({ scale })
  const pixelCount = viewport.width * viewport.height
  if (pixelCount > MAX_RENDER_PIXELS) {
    scale *= Math.sqrt(MAX_RENDER_PIXELS / pixelCount)
    viewport = page.getViewport({ scale })
  }

  return Math.max(1, scale)
}

async function renderPdfPageToImageBuffer(
  page: PdfPageProxyLike,
  canvasFactory: PdfCanvasFactoryLike,
): Promise<Buffer> {
  const viewport = page.getViewport({ scale: resolvePdfRenderScale(page) })
  const canvasAndContext = canvasFactory.create(viewport.width, viewport.height)

  try {
    const renderTask = page.render({
      canvasContext: canvasAndContext.context,
      viewport,
    })
    await renderTask.promise
    const imageBuffer = canvasAndContext.canvas.toBuffer('image/png')
    return Buffer.isBuffer(imageBuffer) ? imageBuffer : Buffer.from(imageBuffer)
  } finally {
    canvasFactory.destroy(canvasAndContext)
  }
}

export async function preparePdfPagesForOcr(filePath: string): Promise<PdfOcrPreparationResult> {
  const { getDocument } = await import('pdfjs-dist/legacy/build/pdf.mjs')
  const data = new Uint8Array(await fs.readFile(filePath))
  const loadingTask = getDocument({
    data,
    cMapUrl,
    cMapPacked: true,
    standardFontDataUrl,
  })

  const pdfDocument = (await loadingTask.promise) as unknown as PdfDocumentProxyLike

  try {
    const pages: PdfPageOcrInput[] = []

    for (let pageNumber = 1; pageNumber <= pdfDocument.numPages; pageNumber += 1) {
      const page = await pdfDocument.getPage(pageNumber)

      try {
        const textContent = await page.getTextContent()
        const extractedText = extractPdfTextContent(textContent.items)

        if (extractedText) {
          pages.push({
            pageNumber,
            extractedText,
            imageBuffer: null,
          })
          continue
        }

        pages.push({
          pageNumber,
          extractedText: null,
          imageBuffer: await renderPdfPageToImageBuffer(page, pdfDocument.canvasFactory),
        })
      } finally {
        page.cleanup()
      }
    }

    return {
      pageCount: pdfDocument.numPages,
      pages,
    }
  } finally {
    await loadingTask.destroy()
  }
}

