import { spawn } from 'node:child_process'
import { writeFile } from 'node:fs/promises'
import readline from 'node:readline'

const [threadId, outputPath] = process.argv.slice(2)
if (!threadId || !outputPath) {
  throw new Error('Usage: node codex-export-thread.mjs <thread-id> <output-path>')
}

const server = spawn('codex', ['app-server', '--stdio'], {
  stdio: ['pipe', 'pipe', 'inherit'],
})
const lines = readline.createInterface({ input: server.stdout })
let settled = false

const fail = (error) => {
  if (settled) return
  settled = true
  server.kill()
  throw error
}

const timeout = setTimeout(() => fail(new Error('Timed out reading Codex thread')), 30_000)

lines.on('line', async (line) => {
  let message
  try {
    message = JSON.parse(line)
  } catch {
    return
  }

  if (message.id === 1 && message.result) {
    server.stdin.write(`${JSON.stringify({ method: 'initialized', params: {} })}\n`)
    server.stdin.write(`${JSON.stringify({
      id: 2,
      method: 'thread/read',
      params: { threadId, includeTurns: true },
    })}\n`)
    return
  }

  if (message.id !== 2) return
  if (message.error) fail(new Error(JSON.stringify(message.error)))

  try {
    await writeFile(outputPath, `${JSON.stringify(message.result.thread, null, 2)}\n`, {
      encoding: 'utf8',
      flag: 'wx',
    })
    settled = true
    clearTimeout(timeout)
    server.stdin.end()
    console.log(outputPath)
  } catch (error) {
    fail(error)
  }
})

server.on('error', fail)
server.stdin.write(`${JSON.stringify({
  id: 1,
  method: 'initialize',
  params: {
    clientInfo: { name: 'session-export', version: '1.0.0' },
    capabilities: { experimentalApi: true },
  },
})}\n`)

